What does this program print? (It is one short string.)

```cpp
#include <print>
#include <stdexcept>

struct Note {
    char c;
    ~Note() { std::print("{}", c); }
};

void inner() {
    Note n{'i'};
    throw std::runtime_error("boom");
}

void outer() {
    Note n{'o'};
    inner();
    std::print("unreached");
}

int main() {
    try {
        Note n{'m'};
        outer();
    } catch (const std::exception&) {
        std::print("c");
    }
    std::println("");
}
```

Using the lesson's `parse_int`, `non_negative` and `describe`, what does this print?

```cpp
auto a = parse_int("-3").transform([](int x) { return x * 2; }).and_then(non_negative);
auto b = parse_int("21").and_then(non_negative).transform([](int x) { return x * 2; });
std::println("{} {}", a ? std::to_string(*a) : std::string(describe(a.error())),
                      b ? std::to_string(*b) : std::string(describe(b.error())));
```
